const config = $input.first().json;
const repo = config.repo;
const token = config.githubToken;
const since = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString();
const headers = {
  Authorization: 'Bearer ' + token,
  Accept: 'application/vnd.github.v3+json',
  'User-Agent': 'weekly-summary'
};

const baseUrl = 'https://api.github.com/repos/' + repo;

const [commits, issues, prs] = await Promise.all([
  this.helpers.httpRequest({
    method: 'GET',
    url: baseUrl + '/commits?since=' + encodeURIComponent(since) + '&per_page=100',
    headers: headers
  }),
  this.helpers.httpRequest({
    method: 'GET',
    url: baseUrl + '/issues?state=closed&since=' + encodeURIComponent(since) + '&per_page=100',
    headers: headers
  }),
  this.helpers.httpRequest({
    method: 'GET',
    url: baseUrl + '/pulls?state=closed&sort=updated&direction=desc&per_page=100',
    headers: headers
  })
]);

const mergedPRs = prs.filter(p => p.merged_at && new Date(p.merged_at) > new Date(Date.now() - 7 * 24 * 60 * 60 * 1000));

return [{
  json: {
    repo: repo,
    discordWebhook: config.discordWebhook,
    language: config.language,
    commits: commits.slice(0, 50),
    issues: issues.filter(i => !i.pull_request).slice(0, 30),
    mergedPRs: mergedPRs.slice(0, 30),
    weekSince: new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
    weekUntil: new Date().toISOString().split('T')[0]
  }
}];

const data = $input.first().json;
const commits = data.commits || [];
const issues = data.issues || [];
const prs = data.mergedPRs || [];

const commitLines = commits.map(c => {
  const msg = c.commit.message.split('\n')[0];
  return '  - ' + msg + ' (' + c.commit.author.name + ', ' + c.sha.substring(0, 7) + ')';
}).join('\n');

const issueLines = issues.map(i => {
  return '  - #' + i.number + ' ' + i.title + ' (by ' + (i.user?.login || 'unknown') + ')';
}).join('\n');

const prLines = prs.map(p => {
  return '  - #' + p.number + ' ' + p.title + ' (by ' + (p.user?.login || 'unknown') + ')';
}).join('\n');

const summaryPrompt = 'Generate a weekly development summary for the period ' + data.weekSince + ' to ' + data.weekUntil + '.\n\n' +
  'Repository activity this week for **' + data.repo + '**:\n\n' +
  '**Commits (' + commits.length + ' total):**\n' + (commitLines || '  (none)') + '\n\n' +
  '**Issues Closed (' + issues.length + ' total):**\n' + (issueLines || '  (none)') + '\n\n' +
  '**Merged PRs (' + prs.length + ' total):**\n' + (prLines || '  (none)') + '\n\n' +
  'Write a concise narrative summary highlighting key changes, trends, and notable events. Use a professional but engaging tone. Group related changes. Start with a one-line headline in bold. Keep it under 1500 characters.';

return [{
  json: {
    model: 'claude-sonnet-4-20250514',
    max_tokens: 4096,
    messages: [{ role: 'user', content: summaryPrompt }],
    _meta: {
      repo: data.repo,
      discordWebhook: data.discordWebhook,
      language: data.language,
      weekSince: data.weekSince,
      weekUntil: data.weekUntil
    }
  }
}];

const claudeResponse = $input.first().json;
const summaryText = claudeResponse.content?.[0]?.text || '';
const meta = $input.first().json._meta || {};

return [{
  json: {
    summary: summaryText,
    repo: meta.repo || 'owner/repo',
    discordWebhook: meta.discordWebhook || '',
    language: meta.language || 'EN',
    weekSince: meta.weekSince || '',
    weekUntil: meta.weekUntil || ''
  }
}];
